:root {
  --bg: #0f1220;
  --panel: #191d31;
  --panel-2: #21263e;
  --text: #e6e8f0;
  --muted: #9aa0b8;
  --accent: #6c8cff;
  --accent-2: #4b6cff;
  --border: #2b3150;
  --danger: #ff6b7d;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}
.topbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px 24px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 5;
}
.topbar h1 { font-size: 20px; margin: 0; }
.search { flex: 1; }
.search input {
  width: 100%;
  max-width: 480px;
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  font-size: 14px;
}
main { display: flex; gap: 24px; padding: 24px; max-width: 1100px; margin: 0 auto; }
.sidebar { width: 220px; flex-shrink: 0; }
.sidebar h2 { font-size: 13px; text-transform: uppercase; letter-spacing: .5px; color: var(--muted); margin: 24px 0 8px; }
.taglist { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 4px; }
.tag-chip {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: var(--text);
  padding: 8px 12px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 14px;
}
.tag-chip:hover { background: var(--panel-2); }
.tag-chip.active { background: var(--accent-2); color: #fff; }
.tag-chip .count { float: right; color: var(--muted); }
.tag-chip.active .count { color: #dbe2ff; }
.content { flex: 1; }
.list { display: flex; flex-direction: column; gap: 12px; }
.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px 18px;
}
.card a.title { color: var(--text); font-weight: 600; font-size: 16px; text-decoration: none; }
.card a.title:hover { color: var(--accent); }
.card .url { color: var(--muted); font-size: 12px; margin: 4px 0; word-break: break-all; }
.card .desc { font-size: 14px; margin: 8px 0; color: #c7cbe0; }
.card .tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.card .tags span {
  background: var(--panel-2);
  color: var(--accent);
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 12px;
}
.card .row { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
.card .btns { display: flex; gap: 6px; flex-shrink: 0; }
.card .btns button {
  background: var(--panel-2);
  border: 1px solid var(--border);
  color: var(--muted);
  border-radius: 8px;
  padding: 4px 10px;
  cursor: pointer;
  font-size: 13px;
}
.card .btns button:hover { color: var(--text); }
.card .btns .del:hover { color: var(--danger); border-color: var(--danger); }
.empty { color: var(--muted); text-align: center; margin-top: 60px; }
button.primary {
  background: var(--accent-2);
  color: #fff;
  border: none;
  border-radius: 10px;
  padding: 10px 16px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
  width: 100%;
}
button.primary:hover { background: var(--accent); }
.modal-backdrop {
  position: fixed; inset: 0;
  background: rgba(0,0,0,.6);
  display: flex; align-items: center; justify-content: center;
  z-index: 20;
}
.modal {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 24px;
  width: 440px;
  max-width: 92vw;
}
.modal h2 { margin: 0 0 16px; }
.modal label { display: block; font-size: 13px; color: var(--muted); margin-bottom: 12px; }
.modal input, .modal textarea {
  width: 100%;
  margin-top: 4px;
  padding: 9px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
}
.modal .actions { display: flex; gap: 10px; justify-content: flex-end; margin-top: 8px; }
.modal .actions button { width: auto; }
.modal .actions button:not(.primary) {
  background: transparent;
  color: var(--muted);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 16px;
  cursor: pointer;
}
@media (max-width: 720px) {
  main { flex-direction: column; }
  .sidebar { width: 100%; }
}

